    <?php $workflow=siw_view($selected);?><section class="system-issue-controls system-issue-workflow" data-system-issue-workflow data-issue-id="<?=(int)$selected['id']?>" data-workflow-stage="<?=htmlspecialchars($workflow['workflow_stage'])?>" data-workflow-version="<?=(int)$workflow['workflow_version']?>" data-action-url="<?=BASE_URL?>/apps/operations/system-issue-action.php" data-csrf="<?=htmlspecialchars(system_issue_csrf())?>"><h3>Controlled repair workflow</h3><div class="system-issue-workflow-progress" aria-label="Repair progress"><?php foreach(['Report','Review','Repair','Test & Deploy','Verify']as$number=>$label):$step=$number+1;?><span class="system-issue-workflow-step <?=$step<(int)$workflow['progress_step']?'is-complete':($step===(int)$workflow['progress_step']?'is-current':'')?>" data-progress-step="<?=$step?>"><?=$step?>. <?=htmlspecialchars($label)?></span><?php endforeach;?></div><div class="system-issue-current-status"><small>Current status</small><strong data-workflow-label><?=htmlspecialchars($workflow['workflow_label'])?></strong><small>Next step</small><p data-workflow-next><?=htmlspecialchars($workflow['next_step'])?></p></div><div class="system-issue-action-panel"><h4 class="system-issue-action-title">Available action</h4><p class="system-issue-action-description">Only actions permitted for this confirmed stage are shown.</p><div class="system-issue-actions" data-workflow-actions><?php foreach($workflow['permitted_actions']as$action):?><button type="button" class="system-issue-action<?=!empty($action['primary'])?' system-issue-action--primary':''?>" data-system-issue-command="<?=htmlspecialchars($action['command'])?>" data-pending-label="<?=htmlspecialchars($action['pending_label'])?>"><?=htmlspecialchars($action['label'])?></button><?php endforeach;?><?php if(!$workflow['permitted_actions']):?><p>No owner action is required at this stage.</p><?php endif;?></div><div class="system-issue-approval-confirmation" data-approval-confirmation hidden><strong>Approve this controlled repair?</strong><p>Your approval is saved first. Queue processing happens separately and cannot erase the decision.</p><label>Optional owner instructions<textarea data-workflow-note maxlength="4000"></textarea></label><div class="system-issue-actions"><button type="button" class="system-issue-action" data-approval-cancel>Cancel</button><button type="button" class="system-issue-action system-issue-action--primary" data-approval-confirm data-pending-label="Approving…">Confirm Approval</button></div></div></div></section><?php endif;?>
   <section class="system-issue-timeline" data-system-issue-activity><h3>Activity</h3><?php foreach($events as$event):?><div><span></span><p><strong><?=htmlspecialchars(ucwords(str_replace('_',' ',$event['event_type'])))?></strong><?=htmlspecialchars($event['message']??'')?><small><?=date('d M Y · H:i',strtotime($event['created_at']))?><?=!empty($event['actor_name'])?' · '.htmlspecialchars($event['actor_name']):''?></small></p></div><?php endforeach;?></section>
   <?php endif;?>
  </aside>
 </div>
</main>
<dialog class="system-issue-dialog" data-report-dialog><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=htmlspecialchars(system_issue_csrf())?>"><input type="hidden" name="action" value="report"><input type="hidden" name="route" value="<?=htmlspecialchars((string)($_SERVER['HTTP_REFERER']??''))?>"><header><div><span>Simple problem report</span><h2>Report a Problem</h2><p>No technical language is needed.</p></div><button type="button" data-close-report aria-label="Close">×</button></header><?php foreach(['problem'=>'What is the problem?','location'=>'Where did it happen?','attempted_action'=>'What were you trying to do?','observed_behaviour'=>'What went wrong?','expected_behaviour'=>'What should have happened?']as$key=>$label):?><label><span><?=htmlspecialchars($label)?></span><textarea name="<?=$key?>" required></textarea></label><?php endforeach;?><label><span>Add screenshot or video <small>Optional</small></span><input type="file" name="evidence[]" multiple accept=".png,.jpg,.jpeg,.webp,.mp4,.pdf"><em>PNG, JPG, WEBP, MP4 or PDF · 25 MB each</em></label><footer><button type="button" class="button" data-close-report>Cancel</button><button class="button primary">Submit problem</button></footer></form></dialog>
<script>document.addEventListener('DOMContentLoaded',()=>{const d=document.querySelector('[data-report-dialog]');document.querySelector('[data-open-report]')?.addEventListener('click',()=>d.showModal());document.querySelectorAll('[data-close-report]').forEach(b=>b.addEventListener('click',()=>d.close()));d?.addEventListener('click',e=>{if(e.target===d)d.close()});if(window.lucide)lucide.createIcons()});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const page=document.getElementById('system-issues-page');if(!page)return;const notify=(message,type='success')=>{if(typeof window.showPortalToast==='function'){window.showPortalToast({title:'System Issues Log',message,type});return}let node=page.querySelector('[data-sil-live-status]');if(!node){node=document.createElement('div');node.dataset.silLiveStatus='true';node.className='system-issues-alert';node.setAttribute('role','status');node.setAttribute('aria-live','polite');page.prepend(node)}node.classList.toggle('is-error',type==='error');node.textContent=message};const fallbackCopy=text=>{const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw new Error('copy_failed')};const copy=page.querySelector('[data-copy-brief]');copy?.addEventListener('click',async()=>{if(copy.disabled)return;copy.disabled=true;const label=copy.querySelector('.sil-copy-label');const original=label?.textContent||'Copy';try{const body=new URLSearchParams({csrf:copy.dataset.csrf||'',issue_id:copy.dataset.issueId||'',brief_version:copy.dataset.briefVersion||''});const response=await fetch(copy.dataset.copyUrl||'',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:body.toString(),credentials:'same-origin'});const data=await response.json();if(!response.ok||!data.ok||typeof data.brief!=='string')throw new Error(data.error||'copy_failed');if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(data.brief);else fallbackCopy(data.brief);copy.classList.add('is-copied');copy.innerHTML='<i data-lucide="check" aria-hidden="true"></i><span class="sil-copy-label">Brief copied</span>';if(window.lucide)lucide.createIcons();notify('Brief copied');setTimeout(()=>{copy.classList.remove('is-copied');copy.innerHTML='<i data-lucide="copy" aria-hidden="true"></i><span class="sil-copy-label">'+original+'</span>';if(window.lucide)lucide.createIcons()},2000)}catch(error){notify('Unable to copy the brief. Please try again.','error')}finally{copy.disabled=false}});const recommendationForm=page.querySelector('[data-owner-recommendation-form]');const recommendationText=recommendationForm?.querySelector('textarea');recommendationText?.addEventListener('input',()=>{recommendationText.style.height='auto';recommendationText.style.height=Math.max(110,recommendationText.scrollHeight)+'px'});recommendationForm?.addEventListener('submit',()=>{recommendationForm.querySelectorAll('button').forEach(button=>button.disabled=true);const update=recommendationForm.querySelector('[data-update-ai-brief]');if(update&&document.activeElement===update)update.textContent='Updating AI Brief…'})});</script>
